import React, { useState } from 'react';

type Proposal = { title: string; fileId: string };
type Props = { storeId: string; proposal?: Proposal; onSubmit: (data: unknown) => void };

export function PlanningScreen({ storeId, proposal, onSubmit }: Props) {
  return <ProposalForm key={JSON.stringify([storeId, proposal?.fileId])} storeId={storeId} proposal={proposal} onSubmit={onSubmit} />;
}

function ProposalForm({ storeId, proposal, onSubmit }: Props) {
  const [form, setForm] = useState<Proposal>({ title: '', fileId: '' });
  return <form onSubmit={e => { e.preventDefault(); onSubmit({ storeId, ...form }); }}>
    <input aria-label=\"Title\" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} />
    <button type=\"button\" onClick={() => proposal && setForm(proposal)}>Use upload</button>
    <button type=\"submit\">Save</button>
  </form>;
}
