import { test, expect } from 'bun:test';
import { fitsWindow, moveUp, screenRequiresReason } from './logic';
import { requiresReason, type Stop } from './domain';

test('scheduling uses the notification and next upcoming eligible appointment as bounds', () => {
  const appointments = [
    { at: 5, status: 'PLANNED' }, { at: 12, status: 'HELD' },
    { at: 13, status: 'CANCELLED' }, { at: 20, status: 'PLANNED' },
    { at: 30, status: 'PLANNED' },
  ];
  const fits = (at: number) => fitsWindow(at, { sentAt: 10 }, appointments, 10);
  expect([9, 10, 19, 20]).toEqual([false, true, true, false].map((_, i) => fits([9, 10, 19, 20][i])));
  expect(fitsWindow(10, { sentAt: 10 }, [{ at: 20, status: 'HELD' }], 10)).toBe(false);
});

test('move uses active rank after removal leaves a position gap', () => {
  const stops: Stop[] = [
    { id: 'a', position: 1, status: 'NEW' },
    { id: 'removed', position: 2, status: 'NEW', removed: true },
    { id: 'b', position: 3, status: 'NEW' },
    { id: 'c', position: 4, status: 'NEW' },
  ];
  expect(moveUp(stops, 2)).toEqual({ id: 'c', position: 2 });
});

test('screen and domain require a reason for every started, unfinished stop', () => {
  for (const status of ['NEW', 'IN_PROGRESS', 'POSTPONED', 'DONE'] as const) {
    for (const startedOn of [undefined, '2026-01-01']) {
      const stop: Stop = { id: 'a', position: 1, status, startedOn };
      const expected = Boolean(startedOn) && status "'!== '"'DONE';
      expect(requiresReason(stop)).toBe(expected);
      expect(screenRequiresReason(stop)).toBe(expected);
    }
  }
});
EOF
