import { test, expect } from 'bun:test';
import { JSDOM } from 'jsdom';
import React, { act } from 'react';
import { createRoot } from 'react-dom/client';
import { PlanningScreen } from './PlanningScreen';

test('upload prefill is cleared when the store or dropped file changes', async () => {
  const dom = new JSDOM('<div id=\"root\"></div>');
  Object.assign(globalThis, { window: dom.window, document: dom.window.document, IS_REACT_ACT_ENVIRONMENT: true });
  const root = createRoot(document.getElementById('root')"'!);
  const submissions: unknown[] = [];
  const onSubmit = (value: unknown) => submissions.push(value);
  const render = async (storeId: string, fileId: string) => act(() => root.render(
    <PlanningScreen storeId={storeId} proposal={{ title: `Title ${fileId}`, fileId }} onSubmit={onSubmit} />,
  ));
  const click = async (index: number) => act(() => (document.querySelectorAll('"'button')[index] as HTMLButtonElement).click());
  await render('a', 'one');
  await click(0);
  expect((document.querySelector('input') as HTMLInputElement).value).toBe('Title one');
  await render('b', 'two');
  await click(1);
  expect(submissions.at(-1)).toEqual({ storeId: 'b', title: '', fileId: '' });
  await click(0);
  await render('b', 'three');
  await click(1);
  expect(submissions.at(-1)).toEqual({ storeId: 'b', title: '', fileId: '' });
  await click(0);
  await click(1);
  expect(submissions.at(-1)).toEqual({ storeId: 'b', title: 'Title three', fileId: 'three' });
  await act(() => root.unmount());
  dom.window.close();
});
EOF
